function undoBuilding(slot){reload();const b=current(),p=b.places.at(-1);if(!p||p.slot!==slot)return;life.undoneBuilding={block:selected,place:structuredClone(p)};city.blocks[selected].lots.pop();b.places.pop();b.focus=b.focus===slot?null:b.focus;selectedSlot=null;selectedResident=null;plannedKind=null;save(true);notify('Undone. All supplies invested in that building are back in your stockpile.');render();}
function restoreUndoneBuilding(){reload();const u=life.undoneBuilding;if(!u||u.block!==selected)return;const b=current();if(b.places.some(p=>p.slot===u.place.slot)||!canBuild(city,u.place.kind,selected))return;if(build(city,u.place.kind,selected)){b.places.push(u.place);delete life.undoneBuilding;selectedSlot=u.place.slot;plannedKind=null;save(true);notify('Your undone building is restored.');render();}}
function buildPlace(kind,slot=selectedSlot,blockIndex=selected){reload();if(blockIndex!==selected||!Object.hasOwn(PROJECTS,kind))return;const b=current();if(!ownsCity||!Number.isInteger(slot)||slot<0||slot>=SLOTS.length||b.places.some(p=>p.slot===slot))return;if(build(city,kind,blockIndex)){construct(life,city.blocks[blockIndex],blockIndex,kind,slot);plannedKind=null;selectedSlot=null;selectedResident=null;save(true);if(!demo)window.ArcadeAnalytics?.capture('city_built',{kind});if(b.arcadeIntent?.kind===kind)delete b.arcadeIntent;notify(PROJECTS[kind].name+' construction started on plot '+(slot+1)+'.');render();setMapMode(false);goalSignature='';renderGoal();}}
