function reload(){const prior=city.earned;if(storage)city=loadCity(storage);for(const k of RESOURCES)if(city.earned[k]>prior[k]){life.events.unshift({text:GAMES[k].name+' delivery: +'+(city.earned[k]-prior[k])+' '+LABELS[k].toLowerCase()+'. Choose a plot to put them to work.'});life.events=life.events.slice(0,8);current().delivery={remaining:7};current().lastDelivery={resource:k,count:city.earned[k]-prior[k],remaining:12};}if(migrateHousing(city,storage))save(true);selected=Math.min(selected,city.blocks.length-1);}
function draw(){if(!city.optedIn)return;paintWorld($('#city'),city.blocks[selected],selected,worldTime,reduced.matches,{...current(),selectedResident});}
function updateLive(){renderGoal();updateOpeningHUD();const b=current();if($('#horse-now')){const p=b.places.find(p=>p.slot===selectedSlot);if(p){const h=horseState(p.slot,b.courtSessions[p.slot]?.clock||0,false,courtCitizen(b,b.courtSessions[p.slot]?.clock||0));$('#horse-now').textContent=h.label+'. '+(h.next==='kid'?h.citizen.name:HERO_NAMES[h.next])+' is up next. '+(h.rebounder==='kid'?h.citizen.name:HERO_NAMES[h.rebounder])+' rebounds and passes the ball back. Families cheer from the sideline.';}}const supply=$('#wallet .spirit strong');if(supply)supply.textContent=life.spirit;updateTargets();const place=b.places.find(p=>p.slot===selectedSlot),active=b.residents.filter(r=>r.stop===selectedSlot&&r.phase==='activity');if($('#place-completed'))$('#place-completed').textContent=place?.completed??0;if($('#place-active'))$('#place-active').textContent=active.length;if($('#place-now'))$('#place-now').textContent=active.length?active.map(r=>r.parent+' & '+r.child).join(', ')+' · '+PROGRAMS[place.kind].verb.toLowerCase()+'.':'No families here yet. Neighbors visit automatically.';if($('#helper-status')&&place){$('#helper-status').textContent=helperStatus(b,place);for(const n of document.querySelectorAll('[data-helper]'))n.textContent=helperButtonText(b,place,n.dataset.helper,n.dataset.helper==='sayed'?'El-Sayed':'Organizer');}if($('#improve-place'))$('#improve-place').disabled=life.spirit<(place?.level??3)*12;for(const n of document.querySelectorAll('[data-resident]')){const r=b.residents.find(r=>r.id===n.dataset.resident),p=b.places.find(p=>p.slot===r?.stop);if(r)n.textContent=r.phase==='activity'?residentActivity(b,r):r.phase==='arrive'?'On the way to '+SHORT[p?.kind??'homes'].toLowerCase():r.phase==='return'?'Heading home together':'At home';}$('#city').setAttribute('aria-label',city.name+', Block '+(selected+1)+'. '+b.places.length+' places, '+b.residents.length+' households. Select a place with the map buttons to see its program and visitors.');const r=b.residents.find(r=>r.phase==='activity'),p=b.places.find(p=>p.slot===r?.stop);$('#live-event').textContent=life.events[0]?.text??(r&&p?r.parent+' & '+r.child+' · '+PROGRAMS[p.kind].verb.toLowerCase()+'.':'The neighborhood is getting its afternoon started.');const bar=$('#service-progress');if(bar){const place=b.places.find(p=>p.slot===selectedSlot),r=b.residents.find(r=>r.stop===selectedSlot&&r.phase==='activity');bar.max=place?.construction?12:place?serviceDuration(b,place):1;bar.value=place?.construction?12-place.construction:r?.timer??0;}}
const scales=[1,1.2,1.4],scaleNames=['Standard','Larger','Largest'];function applyTextScale(){const i=scales.indexOf(Number(life.uiScale));document.documentElement.style.setProperty('--ui-scale',i<0?1:scales[i]);document.body.classList.toggle('large-ui',i>0);if($('#city-text-size'))$('#city-text-size').textContent='Text size: '+scaleNames[Math.max(0,i)];}applyTextScale();if($('#city-text-size'))$('#city-text-size').onclick=()=>{const i=scales.indexOf(Number(life.uiScale)||1);life.uiScale=scales[(i+1)%scales.length];applyTextScale();save();renderGoal();};$('#city-sound').onclick=()=>{life.soundEnabled=!life.soundEnabled;enableCitySound(life.soundEnabled);$('#city-sound').textContent=life.soundEnabled?'Sound on':'Sound off';$('#city-sound').setAttribute('aria-pressed',String(life.soundEnabled));cityCue('delivery');save();};$('#city-sound').textContent=life.soundEnabled?'Sound on':'Sound off';$('#city-sound').setAttribute('aria-pressed',String(!!life.soundEnabled));document.addEventListener('pointerdown',()=>{if(life.soundEnabled)enableCitySound(true);},{once:true});$('#mobile-goal-details').onclick=openProject;$('#goal-details').onclick=openProject;$('#stockpile-open').onclick=()=>{supplyWallet();$('#stockpile-dialog').showModal();};$('#neighbors-open').onclick=()=>{selectedSlot=null;selectedResident=null;renderSelection();$('#inspector').classList.toggle('show-overview');$('#close-inspector').hidden=!$('#inspector').classList.contains('show-overview');syncInspectorDialog();if(matchMedia('(max-width:760px)').matches)$('.world-panel').scrollIntoView({block:'start',behavior:reduced.matches?'instant':'smooth'});};$('#network-open').onclick=()=>{renderNetwork();$('#network-dialog').showModal();};for(const n of document.querySelectorAll('[data-close-dialog]'))n.onclick=()=>$('#'+n.dataset.closeDialog).close();
$('#join').onclick=()=>{reload();city.name=$('#name').value.trim().slice(0,40)||'Our City';city.optedIn=true;welcomeSupplies(city);advanceCity();save(true);if(!demo)window.ArcadeAnalytics?.capture('city_created');render();};
$('#previous').onclick=()=>{selected=Math.max(0,selected-1);selectedSlot=null;selectedResident=null;plannedKind=null;render();};$('#next').onclick=()=>{selected=Math.min(city.blocks.length-1,selected+1);selectedSlot=null;selectedResident=null;plannedKind=null;render();};
$('#close-inspector').onclick=()=>{$('#inspector').classList.remove('show-overview');cancelPlacement();};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.querySelector('dialog[open]'))$('#close-inspector').click();});
$('#pave').onclick=()=>{reload();if(pave(city,selected)){save(true);notify('A smoother street. The whole block gets a safer route home.');render();}};$('#expand').onclick=()=>{reload();if(selected===city.blocks.length-1&&(canExpand(city)||(ambition(current()).completed||ambition(current()).replaying||current().wishDelivered))&&city.blocks.length<10000){city.blocks.push({lots:[],road:false,region:city.region||'detroit'});selected=city.blocks.length-1;selectedSlot=0;selectedResident=null;save(true);notify('A new block. A new set of possibilities.');render();}};
window.addEventListener('storage',e=>{if(!demo&&[KEY,LIFE_KEY,'pa-housing-city-v1'].includes(e.key)){reload();if(e.key===LIFE_KEY)life=loadLife(storage);render();}});window.addEventListener('focus',()=>{if(ownsCity){reload();advanceCity(Date.now(),true);save();render();}else acquireCity();});document.addEventListener('visibilitychange',()=>{visible=!document.hidden;last=0;if(!visible){if(ownsCity){advanceCity();save();}releaseCity?.();}else acquireCity();});window.addEventListener('pagehide',()=>{if(ownsCity){advanceCity();save();}releaseCity?.();});
const map=$('.city-view');function setMapMode(detail){map.classList.toggle('detail',detail);map.classList.toggle('fit',!detail);$('#map-fit').setAttribute('aria-pressed',String(!detail));$('#map-detail').setAttribute('aria-pressed',String(detail));$('#map-hint').textContent=detail?'Drag to explore. Select a building.':'Select a building or an empty plot.';for(const n of $('#lot-targets').children)if(n.classList.contains('empty'))n.querySelector('b').textContent=detail?'+ Build':'+ Build';map.scrollLeft=detail?Math.max(0,(map.scrollWidth-map.clientWidth)/2):0;}
$('#map-fit').onclick=()=>setMapMode(false);$('#map-detail').onclick=()=>setMapMode(true);map.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();map.scrollBy({left:e.key==='ArrowLeft'?-100:e.key==='ArrowRight'?100:0,top:e.key==='ArrowUp'?-100:e.key==='ArrowDown'?100:0,behavior:reduced.matches?'instant':'smooth'});}});
let pan=null,blockMapClick=false;map.addEventListener('pointerdown',e=>{if(e.pointerType==='touch'||e.button!==0)return;pan={x:e.clientX,y:e.clientY,left:map.scrollLeft,top:map.scrollTop,dragging:false};});map.addEventListener('pointermove',e=>{if(!pan)return;const dx=e.clientX-pan.x,dy=e.clientY-pan.y;if(!pan.dragging&&Math.hypot(dx,dy)>8){pan.dragging=true;map.setPointerCapture(e.pointerId);map.classList.add('panning');}if(pan.dragging){map.scrollLeft=pan.left-dx;map.scrollTop=pan.top-dy;e.preventDefault();}});map.addEventListener('pointerup',()=>{if(pan?.dragging){blockMapClick=true;setTimeout(()=>blockMapClick=false,0);}pan=null;map.classList.remove('panning');});map.addEventListener('pointercancel',()=>{pan=null;map.classList.remove('panning');});map.addEventListener('click',e=>{if(blockMapClick){e.preventDefault();e.stopImmediatePropagation();}},true);
function frame(now){if(visible&&(!last||now-last>16)){const dt=last?Math.min((now-last)/1000,.05):0;worldTime+=dt;if(ownsCity&&city.optedIn&&stepLife(life,city.blocks[selected],selected,dt)){save();if(document.activeElement.tagName!=='INPUT'||!$('#project-dialog').contains(document.activeElement))renderAmbition();else renderGoal();if(!$('#inspector').contains(document.activeElement)&&(selectedSlot===null||current().places.some(p=>p.slot===selectedSlot)))renderInspector();}draw();last=now;if(now-lastUI>1000){if(ownsCity)advanceCity();management?.render();updateLive();lastUI=now;}if(ownsCity&&now-lastSave>5000){save();lastSave=now;}}requestAnimationFrame(frame);}
if(demo&&new URLSearchParams(location.search).get('opening')==='ready'){const b=current();beginLeague(b,'open');const a=ambition(b);a.players=b.residents.slice(0,3).map(r=>r.id);a.volunteers=b.residents.slice(0,2).map(r=>r.id);a.coach=b.residents[2].id;}
if(demo){const n=button('Simulate arcade delivery',()=>{const g=goalFor(city,current(),selected,wallet(city)),resource=g.missing?.[0]?.resource;if(!resource){notify('No supplies are missing for the current goal.');return;}const s=loadCity(storage),types={housing:'housing:floor',streets:'pothole:repair',recreation:'vote:basket',care:'outreach:stop',policy:'crashers:policy'};for(let i=0;i<g.missing[0].need;i++)award(s,{id:'lab-'+Date.now()+'-'+i,type:types[resource]});storage.setItem(KEY,JSON.stringify(s));reload();render();},'demo-grant');document.querySelector('.demo-banner').append(n);}
management=createNeighborhoodUI({get:()=>({city,life,b:current(),index:selected}),change:fn=>{if(!ownsCity)return;reload();advanceCity();fn();save();render();},visit:(id,kind)=>{if(id){selectedResident=id;selectedSlot=null;renderSelection();const r=current().residents.find(r=>r.id===id);if(r)focusCamera(r.x,r.y);}else {const p=current().places.find(p=>p.kind===kind),slot=p?.slot??[0,1,2,3,4,5].find(s=>!current().places.some(p=>p.slot===s));if(p)selectLot(p.slot);else if(slot!==undefined)startPlacement(kind);}},demo});
const ownerStatus=document.createElement('p');ownerStatus.className='city-owner-status';ownerStatus.setAttribute('role','status');document.querySelector('#builder').before(ownerStatus);
function ownershipUI(){document.querySelector('#builder').inert=!ownsCity;document.querySelector('#opt-in').inert=!ownsCity;ownerStatus.textContent=ownsCity?'':'Your city is active in another tab. Close that tab or return here after leaving it.';}
async function acquireCity(){
 if(demo||!navigator.locks){ownsCity=true;importRewards();advanceCity(Date.now(),true);save();render();return;}
 if(lockPending||ownsCity||document.hidden)return;lockPending=true;ownershipUI();
 try{await navigator.locks.request('adstoaid-city-simulation',{ifAvailable:true},async lock=>{
  if(!lock||document.hidden)return;ownsCity=true;city=loadCity(storage);life=loadLife(storage);selected=Math.min(selected,city.blocks.length-1);if(migrateHousing(city,storage)||welcomeSupplies(city))save(true);importRewards();advanceCity(Date.now(),true);save();ownershipUI();render();
  await new Promise(resolve=>{releaseCity=resolve;});releaseCity=null;ownsCity=false;ownershipUI();
 });}finally{lockPending=false;}
}
acquireCity();
setInterval(()=>{if(!document.hidden&&!ownsCity)acquireCity();},2000);
render();setMapMode(false);if(city.optedIn&&location.hash==='#neighborhood-plans')management.open();
worldReady.then(()=>{$('#world-loading').hidden=true;draw();}).catch(()=>notify('Neighborhood art is still loading. Reload to try again.'));requestAnimationFrame(frame);
